// Generated by `just generate` from `src/plugins/dotclaude-sessions/slices/usage/domain/builds.ts`. Edit the source and run `just generate`.
// The build of each session: the stamp row of its transcript (P38), and the cost of each build.

import type { StampRecord } from "../../../kernel/stamp.ts";

/** The label of a session with no stamp row. */
export const UNKNOWN_BUILD = "unknown";

/** One main session of the period: its id, its build label, its cost, and the time of its last write. */
export type SessionBuild = {
  id: string;
  build: string;
  cost: number;
  at: number;
};

/** The total of one build: its label, its sessions, and their cost. */
export type BuildTotal = { build: string; count: number; cost: number };

/** The label of a build: the `version` and the `sha` of its stamp row, or `unknown` for no row. */
export const buildOf = (stamp: StampRecord | undefined): string =>
  stamp === undefined ? UNKNOWN_BUILD : `${stamp.version} ${stamp.sha}`;

/** The sessions of each build, and the cost of each build, largest cost first. */
export const buildTotals = (sessions: SessionBuild[]): BuildTotal[] => {
  const totals = new Map<string, BuildTotal>();
  for (const s of sessions) {
    const total = totals.get(s.build) ?? { build: s.build, count: 0, cost: 0 };
    total.count += 1;
    total.cost += s.cost;
    totals.set(s.build, total);
  }
  return [...totals.values()].sort((a, b) => b.cost - a.cost);
};
